1function checkPalindrome(text) {
2
3    // If the string is empty or contains a single character,
4    // the string is a palindrome
5    if (text.length === 0 || text.length === 1) {
6        return true;
7    }
8    
9    // Check if the first and last characters are the same
10    if (text[0] === text[text.length - 1]) {
11
12        // Recursive call
13        return checkPalindrome(text.substring(1, text.length - 1));
14    }
15    else {
16        return false;
17    }
18}
19
